<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_login();require __DIR__.'/config/database.php';$bid=current_business_id();$stmt=$pdo->prepare('SELECT business_name,address,phone,pan_vat FROM businesses WHERE id=? AND is_active=1');$stmt->execute([$bid]);$business=$stmt->fetch();if(!$business){logout_user();header('Location: login.php');exit;}function metric(PDO $pdo,string $sql,array $args):float{$s=$pdo->prepare($sql);$s->execute($args);return(float)$s->fetchColumn();}$products=metric($pdo,'SELECT COUNT(*) FROM products WHERE business_id=? AND is_active=1',[$bid]);$suppliers=metric($pdo,'SELECT COUNT(*) FROM suppliers WHERE business_id=? AND is_active=1',[$bid]);$purchases=metric($pdo,'SELECT COUNT(*) FROM purchases WHERE business_id=?',[$bid]);$totalPurchase=metric($pdo,"SELECT COALESCE(SUM((qty*purchase_rate)-discount+CASE WHEN transport_mode='per_base' THEN transport*(qty*units_per_unit) ELSE transport END+CASE WHEN other_cost_mode='per_base' THEN other_cost*(qty*units_per_unit) ELSE other_cost END),0) FROM purchases WHERE business_id=?",[$bid]);$totalPurchased=metric($pdo,'SELECT COALESCE(SUM(qty*units_per_unit),0) FROM purchases WHERE business_id=?',[$bid]);$totalSold=metric($pdo,"SELECT COALESCE(SUM(si.qty),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND s.status='posted'",[$bid]);$totalStock=$totalPurchased-$totalSold;$dailySales=[];$q=$pdo->prepare("SELECT s.sale_date,COALESCE(SUM(si.qty*si.rate),0)-s.discount+s.vat_amount total FROM sales s LEFT JOIN sale_items si ON si.sale_id=s.id WHERE s.business_id=? AND s.status='posted' GROUP BY s.id,s.sale_date,s.discount,s.vat_amount");$q->execute([$bid]);foreach($q->fetchAll() as $ds){$d=(string)$ds['sale_date'];$dailySales[$d]=($dailySales[$d]??0)+(float)$ds['total'];}$todaySales=0;$lowStock=metric($pdo,"SELECT COUNT(*) FROM products p LEFT JOIN (SELECT product_id,SUM(qty*units_per_unit) q FROM purchases WHERE business_id=? GROUP BY product_id) pu ON pu.product_id=p.id LEFT JOIN (SELECT si.product_id,SUM(si.qty) q FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND s.status='posted' GROUP BY si.product_id) sa ON sa.product_id=p.id WHERE p.business_id=? AND p.is_active=1 AND p.reorder_level>0 AND (COALESCE(pu.q,0)-COALESCE(sa.q,0))<=p.reorder_level",[$bid,$bid,$bid]);$stockValue=metric($pdo,"SELECT COALESCE(SUM((COALESCE(pu.q,0)-COALESCE(sa.q,0))*COALESCE(pu.cost/NULLIF(pu.q,0),0)),0) FROM products p LEFT JOIN (SELECT product_id,SUM(qty*units_per_unit) q,SUM((qty*purchase_rate)-discount+CASE WHEN transport_mode='per_base' THEN transport*(qty*units_per_unit) ELSE transport END+CASE WHEN other_cost_mode='per_base' THEN other_cost*(qty*units_per_unit) ELSE other_cost END) cost FROM purchases WHERE business_id=? GROUP BY product_id) pu ON pu.product_id=p.id LEFT JOIN (SELECT si.product_id,SUM(si.qty) q FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND s.status='posted' GROUP BY si.product_id) sa ON sa.product_id=p.id WHERE p.business_id=? AND p.is_active=1",[$bid,$bid,$bid]);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($business['business_name'])?> • MeroKhata</title><link rel="stylesheet" href="assets/css/style.css"><style>.accountbar{font-size:12px;margin-top:10px;padding-top:10px;border-top:1px solid #ffffff30}.accountbar a{color:#fff}</style></head><body><aside class="sidebar"><div class="brand"><?=htmlspecialchars($business['business_name'])?></div><div class="subbrand">MeroKhata • Online</div><div class="nav"><button class="active">Dashboard</button><button>Products</button><button>Suppliers</button><button>Purchase Entry</button><button>Party / Customer</button><button>Sales & Billing</button><button>Sales Register</button><button>Sales Reports</button><button>Stock / Inventory</button><button>Price Comparison</button></div><div class="accountbar"><?=htmlspecialchars($_SESSION['name']??'User')?> · <?=htmlspecialchars(ucfirst($_SESSION['role']??''))?><br><a href="logout.php">Logout</a></div></aside><main class="main"><div class="topbar"><h1>Dashboard</h1><div class="muted">MeroKhata • Online Database</div></div><section class="panel active"><div class="cards"><div class="card"><div class="label">Products</div><div class="value"><?=number_format($products)?></div></div><div class="card"><div class="label">Suppliers</div><div class="value"><?=number_format($suppliers)?></div></div><div class="card"><div class="label">Purchase Entries</div><div class="value"><?=number_format($purchases)?></div></div><div class="card"><div class="label">Total Purchase</div><div class="value">Rs. <?=number_format($totalPurchase,2)?></div></div><div class="card"><div class="label">Current Stock</div><div class="value"><?=number_format($totalStock,2)?></div></div><div class="card"><div class="label">Stock Value</div><div class="value">Rs. <?=number_format($stockValue,2)?></div></div><div class="card"><div class="label">Today's Sales</div><div class="value" id="todaySalesValue">Rs. <?=number_format($todaySales,2)?></div><div class="muted small" id="todayBsDate"></div></div><div class="card"><div class="label">Low Stock Items</div><div class="value"><?=number_format($lowStock)?></div></div></div><div class="box"><div class="notice"><b>Online Mode:</b> All business modules use the logged-in company's MySQL database.</div></div></section></main><script>window.MK_DAILY_SALES=<?=json_encode($dailySales,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;</script><script src="https://cdn.jsdelivr.net/npm/@remotemerge/nepali-date-converter@1/dist/ndc-browser.js"></script><script src="assets/js/mero-date.js"></script><script>(function(){function run(){if(!window.MeroDate)return;const d=new Date(),p=n=>String(n).padStart(2,'0'),ad=d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate()),bs=MeroDate.convert(ad,'AD');if(!bs)return;const amount=Number((window.MK_DAILY_SALES||{})[bs]||0);document.getElementById('todaySalesValue').textContent='Rs. '+amount.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});document.getElementById('todayBsDate').textContent=bs+' BS · '+ad+' AD';}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',run):run();})();</script><script src="assets/js/online-nav.js"></script></body></html>